('set-glazed-pearl', 'FGL-3910', 'L''Atelier Glazed Pearl & Foil', 'Chrome', 'Iridescent glazed pearl almond silhouette with hand-placed 24k champagne gold foil accents', '/assets/editorial_nail_hero.jpg', 'linear-gradient(145deg, #FAF7F2 0%, #F4EFEB 55%, #EAD7A1 100%)', 'warm-ivory', 75, 642, true, true, '{"thumb":{"finger":"thumb","title":"Pearl Glaze Base","baseColor":"#FAF0EA","accentColor":"#E5C697","pattern":"solid","shape":"almond","length":"medium","finish":"chrome","clientNote":"Apex reinforced with rubber base. Flash-cure 20s no-wipe topcoat and burnish fine pearl chrome powder.","status":"detected"},"index":{"finger":"index","title":"Gold Foil Free Edge","baseColor":"#FAF0EA","accentColor":"#E5C697","pattern":"glitter-ombre","shape":"almond","length":"medium","finish":"chrome","clientNote":"Delicate 24k gold leaf flakes floated near smile line over glazed pearl.","status":"detected"},"middle":{"finger":"middle","title":"Glazed Donut Shimmer","baseColor":"#FAF0EA","accentColor":"#FFFFFF","pattern":"aura","shape":"almond","length":"medium","finish":"chrome","clientNote":"High-shine pearl mirror reflection with semi-sheer Milky Glaze undertone.","status":"detected"},"ring":{"finger":"ring","title":"Champagne Foil Swirl","baseColor":"#FAF0EA","accentColor":"#E5C697","pattern":"chrome-swirl","shape":"almond","length":"medium","finish":"chrome","clientNote":"3D architectural embossing gel ribbon rubbed with molten champagne chrome.","status":"detected"},"pinky":{"finger":"pinky","title":"Pearl Glaze Minimal","baseColor":"#FAF0EA","accentColor":"#E5C697","pattern":"solid","shape":"almond","length":"medium","finish":"chrome","clientNote":"Glass topcoat cured 60s LED with cuticle hydration.","status":"detected"}}'::jsonb),
