('set-blush-daisy', 'FGL-8492', 'Rose Water & Micro-French Petals', 'Floral', 'Translucent blush almond base with razor-thin white tips and hand-painted micro botanical petals', 'https://images.unsplash.com/photo-1604654894610-df63bc536371?auto=format&fit=crop&w=800&q=85', 'linear-gradient(145deg, #FDE8EE 0%, #F7D4DF 55%, #EAD9F2 100%)', 'porcelain', 70, 532, true, true, '{"thumb":{"finger":"thumb","title":"Rose Water French","baseColor":"#F9D8E0","accentColor":"#FFFFFF","pattern":"classic-french","shape":"almond","length":"medium","finish":"glossy","clientNote":"Translucent Rose Water rubber base. Precision 0.5mm French smile line in Atelier Blanc.","status":"detected"},"index":{"finger":"index","title":"Rose Water French","baseColor":"#F9D8E0","accentColor":"#FFFFFF","pattern":"classic-french","shape":"almond","length":"medium","finish":"glossy","clientNote":"Match thumb smile line depth and curve curvature.","status":"detected"},"middle":{"finger":"middle","title":"Rose Water French","baseColor":"#F9D8E0","accentColor":"#FFFFFF","pattern":"classic-french","shape":"almond","length":"medium","finish":"glossy","clientNote":"Optically clear leveling topcoat cured 60s LED.","status":"detected"},"ring":{"finger":"ring","title":"Micro Botanical Bloom","baseColor":"#F9D8E0","accentColor":"#FFFFFF","pattern":"floral","shape":"almond","length":"medium","finish":"glossy","clientNote":"Delicate 5-petal hand-painted micro daisy with tiny Champagne Dust center core.","status":"detected"},"pinky":{"finger":"pinky","title":"Rose Water French","baseColor":"#F9D8E0","accentColor":"#FFFFFF","pattern":"classic-french","shape":"almond","length":"medium","finish":"glossy","clientNote":"Hairline tip along pinky apex.","status":"detected"}}'::jsonb),
